# -*- coding: utf-8 -*-
"""Science Stage 8 · Unit 1 Diet and Growth – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 8 (8Bp.01–8Bp.03, 8SIC.05)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 1.1 Nutrients in food · 8Bp.01, 8Bp.02
# =====================================================================================================
READ["1.1"] = L(
    H("Why do we eat?",
      "A car needs fuel, a house needs bricks, and a factory needs workers to keep it running. Your body needs all three – and it gets them from food.",
      "Write down three things your body uses food for, then check your list in this lesson."),
    I("Why we need food",
      "Food gives us **nutrients**: substances the body needs for **energy**, as **building materials** for growth and repair, and to **control** body processes.",
      table=[["Nutrient", "Main job", "Good sources"],
             ["**carbohydrates**", "main source of energy", "rice, bread, noodles, potatoes, maize"],
             ["**proteins**", "growth and repair of cells; making enzymes and hormones", "fish, eggs, meat, milk, beans, lentils, tofu"],
             ["**fats and oils**", "store energy; insulate the body; protect organs; build cell membranes", "butter, cooking oil, nuts, avocado"],
             ["**vitamins**", "help the body work correctly (needed in tiny amounts)", "fruit, vegetables, milk, fish"],
             ["**minerals**", "help the body grow and work properly (tiny amounts)", "milk, green vegetables, red meat, beans"]],
      then=["We also need **water** (most of blood and cells is water; it is needed for chemical reactions) and **fibre** (keeps the gut working). They are essential but are not usually called nutrients."]),
    I("Predict, watch, explain: which foods contain starch?",
      "**Iodine solution** is orange-brown. It turns **blue-black** when **starch** is present. A drop is put on four foods.",
      table=[["Food", "Colour with iodine", "Starch?"], ["cooked rice", "blue-black", "yes"], ["a slice of cucumber", "orange-brown", "no (hardly any)"],
             ["a cracker", "blue-black", "yes"], ["a piece of chicken", "orange-brown", "no"]],
      then=["Rice and crackers are made from grains, which store starch. Chicken is mostly protein and fat. Sugar would also stay orange-brown: it is a carbohydrate, but not starch."]),
    I("Carbohydrates: fuel for the body",
      "Carbohydrates are the body's main **fuel** for moving, keeping warm and even thinking.",
      table=[["Type", "Found in", "Notes"],
             ["**starch** (complex)", "rice, bread, pasta, oats, potatoes", "releases energy steadily; main energy source"],
             ["**sugars** (simple)", "sweets, honey, fizzy drinks, fruit", "absorbed quickly – fast energy; refined sugar has no other nutrients"],
             ["**fibre**", "vegetables, fruit, whole grains, beans", "cannot be digested; adds bulk, helps food move through the gut, prevents constipation, keeps you full"]],
      then=["Extra carbohydrate that the body does not use is turned into **fat** and stored. **Carbohydrates and fats are the body's main energy stores.**"]),
    I("Vitamins and minerals",
      "Vitamins and minerals are needed only in tiny amounts, but without them we become ill.",
      table=[["Vitamin or mineral", "Why we need it", "Sources", "Lack of it causes"],
             ["vitamin A", "healthy eyes (seeing in dim light) and skin", "carrots, sweet potato, liver, green vegetables", "poor night vision"],
             ["vitamin C", "healthy skin, gums and blood vessels; helps wounds heal", "citrus fruit, guava, peppers", "scurvy (bleeding gums)"],
             ["vitamin D", "helps the body absorb calcium for strong bones", "oily fish, eggs; made in skin in sunlight", "rickets (soft, bent bones)"],
             ["**calcium**", "strong bones and teeth; muscles and nerves", "milk, cheese, yoghurt, small fish with bones", "weak bones and teeth"],
             ["**iron**", "making haemoglobin in red blood cells, to carry oxygen", "red meat, beans, spinach, eggs", "anaemia (tiredness, pale skin)"]]),
    Y("Match the nutrient",
      grid("s8u01r11", "Which nutrient is needed most for each job?", ["Protein", "Carbohydrate", "Calcium", "Iron"],
           [("repairing a cut on your knee", "Protein"), ("energy for a football match", "Carbohydrate"), ("making haemoglobin", "Iron"), ("strong teeth", "Calcium")],
           "Think of the main job of each nutrient.", "Repair = protein; energy = carbohydrate; haemoglobin = iron; teeth and bones = calcium.")),
    I("Real data: energy in one gram",
      "Energy released by 1 g of each nutrient (approximately):",
      fig={"kind": "barchart", "labels": ["carbohydrate", "protein", "fat"], "values": [17, 17, 37], "ymax": 40, "step": 10, "ylabel": "energy (kJ per gram)", "xlabel": "nutrient"},
      then=["Fat stores more than **twice** as much energy per gram as carbohydrate or protein. That is why the body stores extra energy as fat."]),
    Y("Energy in a snack",
      num("s8u01r12", "A snack contains 10 g of fat. About how much energy does the fat provide, in kJ? (1 g of fat ≈ 37 kJ)", 370, "Multiply the mass by the energy per gram.",
          "10 × 37 = 370 kJ.", errs=[(47, "Multiply, do not add.")])),
    K("Key points",
      "Nutrients: **carbohydrates** (energy), **proteins** (growth and repair), **fats** (energy store, insulation, protection), **vitamins** and **minerals**.",
      "Water and fibre are essential too. Iodine turns blue-black with **starch**.",
      "Vitamin A – eyes; C – skin, gums, healing; D – absorbing calcium; calcium – bones and teeth; iron – haemoglobin.",
      "Fat gives about 37 kJ/g, carbohydrate and protein about 17 kJ/g; carbohydrates and fats are the main energy stores."),
    book=BK(
        [("nutrient", "a substance in food the body needs"), ("carbohydrate", "a nutrient that gives energy, e.g. starch and sugar"), ("protein", "a nutrient for growth and repair"),
         ("vitamin", "a nutrient needed in tiny amounts to keep the body working"), ("mineral", "a nutrient such as calcium or iron, needed in small amounts"),
         ("fibre", "plant material we cannot digest that keeps the gut healthy"), ("starch", "a complex carbohydrate stored by plants")],
        [], [],
        [Ex("Give the main job of: (a) protein (b) carbohydrate (c) fat.", ans="(a) growth and repair (b) energy (c) energy store, insulation, protection of organs"),
         Ex("Describe the test for starch and the result.", ans="add orange-brown iodine solution; it turns blue-black if starch is present"),
         Ex("Name the vitamin or mineral that:", ("helps us see in dim light", "vitamin A"), ("prevents scurvy", "vitamin C"), ("is needed to make haemoglobin", "iron"), ("helps the body absorb calcium", "vitamin D")),
         Ex("Why is fibre important even though it is not digested?", ans="It adds bulk so food and waste move through the gut, prevents constipation and helps you feel full."),
         Ex("A long-distance runner eats a large plate of pasta the night before a race. Explain why.", ans="Pasta is rich in starch, which gives a steady release of energy and is stored for the race.", think=True)],
        ["name the nutrients and their jobs", "describe the test for starch", "explain the jobs of vitamins A, C and D, calcium and iron", "compare the energy in carbohydrate, protein and fat"],
        look=["the nutrient table", "the vitamins and minerals table"],
        note="Read it after the video: nutrients and their jobs, the starch test and energy in food (answers at the back)."),
)

# =====================================================================================================
# 1.2 A balanced diet · 8Bp.01, 8Bp.03
# =====================================================================================================
READ["1.2"] = L(
    H("Same lunch for everyone?",
      "A 13-year-old footballer, a 70-year-old grandmother and a baby all sit down to lunch.",
      "Should they eat the same amounts? Why or why not?"),
    I("Energy in and energy out",
      "**Energy in** comes from food. **Energy out** is used for living: breathing, growing, keeping warm, moving and thinking.",
      table=[["If energy in is …", "the body …"], ["equal to energy out", "keeps the same mass"], ["more than energy out (for a long time)", "stores the extra as fat – mass goes up"],
             ["less than energy out (for a long time)", "uses its stores – mass goes down, and the person feels weak and tired"]],
      then=["Energy needs depend on **age**, **sex**, **how active** you are and individual differences. Teenagers who are growing fast need a lot of energy, protein and calcium."]),
    I("Real data: daily energy needs",
      "Approximate daily energy needs:",
      fig={"kind": "barchart", "labels": ["child (5)", "girl (14)", "boy (14)", "office worker", "builder", "athlete"], "values": [6500, 9000, 11000, 9500, 13000, 15000], "ymax": 16000, "step": 4000,
           "ylabel": "energy per day (kJ)", "xlabel": "person"}),
    I("What is a balanced diet?",
      "A **balanced diet** contains a **variety** of foods that give all the nutrients, water and fibre we need, in the right amounts.",
      fig=CARD("A healthy plate", [{"t": "½ fruit and vegetables", "d": "vitamins, minerals, fibre"}, {"t": "¼ starchy food", "d": "wholegrain if possible: energy and fibre"},
                                   {"t": "¼ protein", "d": "fish, eggs, beans, meat"}, {"t": "water to drink", "d": "not sugary drinks"}], 4),
      then=["Use small amounts of healthier oils, and stay active."]),
    I("Malnutrition",
      "**Malnutrition** means not getting the right amounts of nutrients – too little **or** too much.",
      table=[["Problem", "Cause", "Effects"], ["**kwashiorkor**", "severe lack of protein", "swollen belly, poor growth, weak muscles"],
             ["**obesity**", "much more energy in than out for a long time", "higher risk of heart disease, high blood pressure, type 2 diabetes, joint problems"],
             ["**starvation**", "too little food overall", "weak, tired, thin; poor growth"], ["deficiency diseases", "lack of one vitamin or mineral", "scurvy, rickets, anaemia"]]),
    Y("What is missing?",
      mcq("s8u01r21", "Ali's lunch is crisps, a chocolate bar and a fizzy drink. Which is the biggest problem?",
          [("It has almost no protein, vitamins or fibre, and too much sugar, fat and salt.", True, "Yes – it is high in energy but low in most other nutrients."),
           ("It has no carbohydrate.", False, "Crisps, chocolate and fizzy drinks are full of carbohydrate."), ("It has too much fibre.", False, "It has hardly any fibre."),
           ("It has too much protein.", False, "It has very little protein.")],
          "Check each nutrient in turn.", "Lots of energy, sugar, fat and salt; very little protein, vitamins, minerals or fibre.")),
    I("Real life: a balanced lunch box",
      "One balanced lunch, item by item:",
      table=[["Item", "Main nutrients"], ["wholemeal wrap", "starch (energy) and fibre"], ["egg or bean filling", "protein for growth and repair"],
             ["carrot and cucumber sticks", "vitamin A, fibre"], ["a guava or an orange", "vitamin C, fibre"], ["small pot of yoghurt", "calcium and protein"], ["water", "keeps you hydrated, no sugar"]]),
    K("Key points",
      "Energy in = energy out keeps body mass steady; more in → fat stored; less in → stores used.",
      "Energy needs depend on age, sex and activity.",
      "A **balanced diet**: half fruit and vegetables, a quarter starchy food, a quarter protein, plus water.",
      "**Malnutrition**: too little (kwashiorkor, starvation, deficiencies) or too much (obesity)."),
    book=BK(
        [("balanced diet", "a variety of foods giving all the nutrients in the right amounts"), ("malnutrition", "not getting the right amounts of nutrients"),
         ("kwashiorkor", "a disease caused by a severe lack of protein"), ("obesity", "having a lot of extra body fat")],
        [], [],
        [Ex("Give three things that affect how much energy a person needs.", ans="age, sex, activity (also body size / individual differences)"),
         Ex("Use the chart: how much more energy per day does a builder need than an office worker?", ans="13 000 − 9500 = 3500 kJ"),
         Ex("Explain what happens if a person takes in more energy than they use for many months.", ans="The extra energy is stored as fat, so they gain mass and may become obese."),
         Ex("Plan a balanced breakfast and say which nutrient each item gives.", ans="e.g. porridge (starch, fibre), milk (calcium, protein), banana (vitamins, fibre), boiled egg (protein)"),
         Ex("Explain why malnutrition can affect people who eat too much as well as people who eat too little.", ans="Malnutrition means the wrong amounts of nutrients – too much energy can cause obesity, too little causes starvation or deficiencies.", think=True)],
        ["explain energy balance", "describe a balanced diet", "explain the effects of malnutrition"],
        look=["energy in and energy out", "the healthy plate"],
        note="Read it after the video: energy balance, a balanced diet and malnutrition (answers at the back)."),
)

# =====================================================================================================
# 1.3 Healthy and unhealthy habits · 8Bp.03, 8SIC.05
# =====================================================================================================
READ["1.3"] = L(
    H("Habits that last",
      "The habits you form as a teenager – what you eat, how much you sleep and move – often stay with you for life.",
      "Name one healthy habit you already have and one you would like to start."),
    I("Healthy habits",
      "Diet is only part of good health.",
      table=[["Habit", "Why it helps"], ["enough **sleep** (about 9 hours for teenagers)", "the body grows and repairs; better memory, concentration and mood; fewer infections"],
             ["regular **exercise**", "stronger heart, lungs, muscles and bones; healthy body mass; better mood"], ["warm up and cool down", "prevents injuries"],
             ["stretching, yoga", "flexible joints and muscles"]]),
    I("Real data: resting heart rate",
      "A student exercised for 30 minutes, five times a week, and measured her resting heart rate every two weeks.",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 8, "step": 2, "label": "time (weeks)"}, "y": {"min": 60, "max": 85, "step": 5, "label": "resting heart rate (beats/min)"},
           "series": [{"pts": [[0, 81], [2, 78], [4, 75], [6, 73], [8, 71]]}]},
      then=["Her resting heart rate fell from 81 to 71 beats per minute. Exercise makes the heart muscle stronger, so it pumps more blood with each beat – it needs fewer beats at rest."]),
    Y("Read the graph",
      num("s8u01r31", "By how many beats per minute did her resting heart rate fall over the 8 weeks?", 10, "Subtract the final value from the first.", "81 − 71 = 10 beats per minute.")),
    I("Unhealthy habits",
      "Some habits harm growth and health.",
      table=[["Habit", "Harm"],
             ["lots of sugar, salt and saturated fat", "tooth decay, weight gain, type 2 diabetes, high blood pressure, heart disease"],
             ["too little protein, calcium or vitamin D", "stunted growth, weak bones"],
             ["alcohol", "harms the brain and liver; addiction; in pregnancy it can damage the baby's brain and slow its growth"],
             ["smoking and vaping", "**nicotine** – addictive, raises heart rate and blood pressure; **carbon monoxide** – stops blood carrying oxygen; **tar** – coats the lungs, causes lung cancer"]],
      then=["Second-hand smoke harms people nearby, including children, whose growth and lungs can be damaged. Vapes still contain addictive nicotine and other harmful chemicals."]),
    Y("Which substance?",
      grid("s8u01r32", "Which substance in tobacco smoke causes each effect?", ["Nicotine", "Carbon monoxide", "Tar"],
           [("makes smoking addictive", "Nicotine"), ("stops red blood cells carrying oxygen", "Carbon monoxide"), ("coats the lungs and can cause cancer", "Tar")],
           "Three substances, three effects.", "Nicotine is addictive; carbon monoxide blocks oxygen transport; tar coats the lungs.")),
    I("Food choices and the environment",
      "Cattle give off **methane**, and clearing land for grazing and animal feed can lead to **deforestation** – both add to climate change.",
      then=["Food scientists make **plant-based burgers** from peas, beans, rice flour and vegetables. Pea protein contains all the essential building blocks the body needs. Eating more plant-based food can help the environment, as long as the diet still gives all the nutrients – especially protein, iron and vitamin B12."]),
    K("Key points",
      "Sleep and regular exercise support growth and health; exercise lowers resting heart rate.",
      "Too much sugar, salt and fat, or too little protein, calcium and vitamin D, harm health and growth.",
      "Alcohol, smoking and vaping are harmful: nicotine (addictive), carbon monoxide (less oxygen carried), tar (lung cancer).",
      "Food choices affect the environment; plant-based foods can reduce greenhouse gases."),
    book=BK(
        [("nicotine", "the addictive drug in tobacco and vapes"), ("carbon monoxide", "a poisonous gas that stops blood carrying oxygen"), ("tar", "a sticky substance in smoke that coats the lungs"),
         ("resting heart rate", "the number of heartbeats per minute at rest")],
        [], [],
        [Ex("Give two benefits of regular exercise and two of enough sleep.", ans="exercise: stronger heart, healthy mass; sleep: growth and repair, better concentration"),
         Ex("Name the three harmful substances in tobacco smoke and the effect of each.", ans="nicotine – addictive, raises heart rate; carbon monoxide – less oxygen carried; tar – coats lungs, cancer"),
         Ex("Why should pregnant women not drink alcohol?", ans="It can damage the baby's brain and slow its growth."),
         Ex("Quick quiz.", ("Which nutrient is needed for growth and repair?", "protein"), ("Why do we need vitamin D?", "to absorb calcium for strong bones"),
            ("What disease is caused by a severe lack of protein?", "kwashiorkor"), ("What is the test for starch?", "iodine turns blue-black")),
         Ex("Give one environmental benefit and one possible risk of switching to a plant-based diet.", ans="Benefit: fewer greenhouse gases / less deforestation. Risk: missing nutrients such as iron, protein or vitamin B12 if not planned.", think=True)],
        ["explain how sleep and exercise help health", "describe the effects of alcohol, smoking and vaping", "discuss how food choices affect the environment"],
        look=["the heart rate graph", "the harmful substances in smoke"],
        note="Read it after the video: healthy and unhealthy habits and sustainable food, plus a quick quiz (answers at the back)."),
)
